#!/usr/bin/env python3
"""Deploy only authenticated original data into the fresh Cell05 gaps stage."""
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import tarfile
import urllib.request

STAGE = Path('/workspace/p26-cell05-all-row-gaps-20261127-v1')
URL = 'https://raw.githubusercontent.com/UyNewNas/goldbach-formalization/8e546e4c8131ab3e5c600a4796a7690552b5d026/docs/verification/20261127-p26/cell05-all-row-gaps/inputs/pure2-original-evidence.tar.xz'
SHA = '874cf979a761f81d76761b937e76c81d6ee635244e734285280a79e949840960'
TRANSPORT_SHA = 'e4515252ec4bbc5f3066a8a5967ae384ab71ce6cbd181b0dd7bf6a221f43a4c3'


def fp(body):
    return {'bytes': len(body), 'sha256': hashlib.sha256(body).hexdigest()}


def save(path, body):
    assert path.is_absolute() and '..' not in path.parts
    for parent in path.parents:
        assert not parent.is_symlink(), str(parent)
    path.parent.mkdir(parents=True, exist_ok=True)
    assert not path.is_symlink()
    if path.exists():
        assert path.is_file() and path.read_bytes() == body, f'Existing file differs: {path}'
    else:
        with path.open('xb') as f:
            f.write(body)
    assert path.read_bytes() == body


body = urllib.request.urlopen(URL, timeout=60).read()
assert fp(body) == {'bytes': 266236, 'sha256': SHA}
with tarfile.open(fileobj=io.BytesIO(body), mode='r:xz') as tar:
    members = tar.getmembers()
    assert len(members) == 17 and len({m.name for m in members}) == 17
    contents = {}
    for m in members:
        p = PurePosixPath(m.name)
        assert m.isfile() and not p.is_absolute() and '..' not in p.parts
        contents[m.name] = tar.extractfile(m).read()
    transport_body = contents['TRANSPORT.json']
    assert fp(transport_body) == {'bytes': 17815, 'sha256': TRANSPORT_SHA}
    transport = json.loads(transport_body)
    expected = {r['relative_path']: r for r in transport['files']}
    assert set(contents) == set(expected) | {'TRANSPORT.json'}
    for name, row in expected.items():
        assert fp(contents[name]) == {k: row[k] for k in ('bytes', 'sha256')}
save(STAGE / 'inputs/pure2-original-evidence.tar.xz', body)
for name, data in contents.items():
    save(STAGE / 'inputs/pure2' / name, data)
matches = []
excluded_names = {'.git', 'node_modules', 'toolchains', 'compile-deps'}
for parent, dirs, files in os.walk('/workspace', followlinks=False):
    dirs[:] = [d for d in dirs if d not in excluded_names and not Path(parent, d).is_symlink()]
    for n in files:
        if n.startswith('P2OriginalSaving19Cell05AllRowGaps.'):
            p = Path(parent, n)
            matches.append({'path': str(p), **fp(p.read_bytes())})
report = {
    'schema': 'p26_cell05_all_row_gaps_pure2_deployment_v1',
    'stage': str(STAGE), 'url': URL, 'archive': fp(body),
    'transport': fp(transport_body), 'members': len(contents),
    'expanded_bytes': sum(map(len, contents.values())),
    'target_dedup_matches': matches,
    'dedup_excluded_directory_names': sorted(excluded_names),
    'Lean_commands': 0, 'old_proof_replays': 0,
}
encoded = (json.dumps(report, indent=2) + '\n').encode()
save(STAGE / 'inputs/PURE2_DEPLOYMENT.json', encoded)
print(encoded.decode(), end='')

P26_PURE2_DEPLOY
